public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Collect all possible substrings from each string
    TreeSet<String> allSubstrings = new TreeSet<>((a, b) -> {
        // Sort by length first, then lexicographically
        int lenCompare = a.length() - b.length();
        if (lenCompare != 0) {
            return lenCompare;
        }
        return a.compareTo(b);
    });

    for (String s : strings) {
        if (s == null || s.isEmpty()) {
            continue;
        }
        int n = s.length();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j <= n; j++) {
                String substring = s.substring(i, j);
                allSubstrings.add(substring);
                allSubstrings.add(new StringBuilder(substring).reverse().toString());
            }
        }
    }

    // Now find the largest string X such that X or X.reversed() is a substring of at least one string?
    // Re-reading: "finds the largest string X, such that either X, or its inverse can be found as a substring of any of the given strings."
    // This means: for the string X, X must appear as a substring in at least one of the given strings, OR the reverse of X must appear as a substring in at least one of the given strings.
    // So we want the maximum length of such an X.

    // Since we have all substrings and their reverses already in the TreeSet (sorted by length descending when we iterate), 
    // we can iterate from the largest substring and check if either itself or its reverse is a substring of any of the original strings.

    // Actually, we can simplify: for each candidate substring (from our collected set), we check if it appears in any of the strings, or if its reverse appears in any of the strings.
    // But we want the largest such X.

    // Let's iterate through the TreeSet in reverse order (largest first)
    List<String> substringsList = new ArrayList<>(allSubstrings);
    substringsList.sort((a, b) -> {
        int lenCompare = b.length() - a.length(); // descending by length
        if (lenCompare != 0) {
            return lenCompare;
        }
        return a.compareTo(b);
    });

    for (String candidate : substringsList) {
        String rev = new StringBuilder(candidate).reverse().toString();
        boolean found = false;
        for (String s : strings) {
            if (s == null) {
                continue;
            }
            if (s.contains(candidate) || s.contains(rev)) {
                found = true;
                break;
            }
        }
        if (found) {
            return candidate.length();
        }
    }

    return 0;
}

