public static int countPrefixWords(List<String> wordList, String prefix) {
    if (wordList == null || prefix == null) {
        throw new IllegalArgumentException("wordList and prefix must not be null");
    }

    int count = 0;
    for (String word : wordList) {
        if (word != null) {
            if (word.length() >= prefix.length()) {
                if (word.substring(0, prefix.length()).equals(prefix)) {
                    count++;
                }
            }
        }
    }
    return count;
}

