public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create adjacency list
    java.util.List<Integer>[] adjList = new java.util.List[n * n];
    for (int i = 0; i < n * n; i++) {
        adjList[i] = new java.util.ArrayList<>();
    }

    // Build the graph
    for (int[] path : paths) {
        if (path.length >= 2) {
            int from = path[0] * n + path[1];
            int to = path[2] * n + path[3];
            adjList[from].add(to);
            adjList[to].add(from);
        }
    }

    int startId = start[0] * n + start[1];
    int endId = end[0] * n + end[1];

    // BFS to find if there's a path from start to end
    java.util.Queue<Integer> queue = new java.util.LinkedList<>();
    boolean[] visited = new boolean[n * n];
    queue.offer(startId);
    visited[startId] = true;

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == endId) {
            return "can be travelled";
        }
        int x = current / n;
        int y = current % n;
        // Check all 4 possible directions
        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (int[] dir : directions) {
            int nx = x + dir[0];
            int ny = y + dir[1];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n) {
                int neighborId = nx * n + ny;
                if (!visited[neighborId] && adjList[current].contains(neighborId)) {
                    visited[neighborId] = true;
                    queue.offer(neighborId);
                }
            }
        }
    }

    return "cannot be travelled";
}

