public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        return "appx(" + word1 + ", " + word2 + ") = 0/1";
    }

    int len1 = word1.length();
    int len2 = word2.length();
    int sumOfLengths = len1 + len2;

    if (sumOfLengths == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0/1";
    }

    // Convert to uppercase for case-insensitive comparison
    word1 = word1.toUpperCase();
    word2 = word2.toUpperCase();

    // Count common letters
    int[] freq1 = new int[26];
    int[] freq2 = new int[26];

    for (char c : word1.toCharArray()) {
        if (c >= 'A' && c <= 'Z') {
            freq1[c - 'A']++;
        }
    }

    for (char c : word2.toCharArray()) {
        if (c >= 'A' && c <= 'Z') {
            freq2[c - 'A']++;
        }
    }

    int commonCount = 0;
    for (int i = 0; i < 26; i++) {
        commonCount += Math.min(freq1[i], freq2[i]);
    }

    // Calculate GCD for simplification
    int numerator = commonCount;
    int denominator = sumOfLengths;

    int gcd = gcd(numerator, denominator);

    numerator /= gcd;
    denominator /= gcd;

    StringBuilder result = new StringBuilder();
    result.append("appx(").append(word1.toLowerCase()).append(", ").append(word2.toLowerCase()).append(") = ");

    if (denominator == 1) {
        result.append(numerator);
    } else {
        result.append(numerator).append("/").append(denominator);
    }

    return result.toString();
}

