public boolean canArrange(int[] arr, int k) {
        if (arr == null || arr.length == 0) {
            return true;
        }
        if (arr.length % 2 != 0) {
            return false;
        }
        if (k <= 0) {
            return false;
        }

        int[] remainderCounts = new int[k];
        for (int num : arr) {
            int mod = num % k;
            if (mod < 0) {
                mod += k;
            }
            remainderCounts[mod]++;
        }

        if (remainderCounts[0] % 2 != 0) {
            return false;
        }

        for (int i = 1; i <= k / 2; i++) {
            int complement = (k - i) % k;
            if (remainderCounts[i] != remainderCounts[complement]) {
                return false;
            }
        }

        return true;
    }

