public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }

    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }

    // dp[i] represents the minimum cost to reach step i
    // You can start from step 0 or step 1, so dp[0] and dp[1] are 0
    // But since you have to pay the cost of the step you're on when you step on it,
    // the recurrence is: dp[i] = min(dp[i-1] + cost[i-1], dp[i-2] + cost[i-2])

    // We want to reach the "top" which is step n (beyond the last step)
    // So we need dp[n]

    // Alternatively, we can think of it as:
    // Let dp[i] = minimum cost to reach step i (and you are standing on step i)
    // Then dp[0] = cost[0], dp[1] = cost[1]
    // dp[i] = cost[i] + min(dp[i-1], dp[i-2])
    // Answer = min(dp[n-1], dp[n-2]) because you can reach the top from step n-1 (climbing 1) or step n-2 (climbing 2)

    // But the standard approach:
    // Let dp[i] be the minimum cost to reach step i (the cost of stepping on i is already paid)
    // Actually, the common interpretation: to reach step i, you either came from i-1 or i-2, and you pay the cost of the step you're moving TO? 
    // No, the problem says: "cost[i] is the cost of ith step", and when you step on it, you pay it.
    // You start for free at step 0 or step 1.
    // So: dp[0] = 0, dp[1] = 0
    // dp[i] = min(dp[i-1] + cost[i-1], dp[i-2] + cost[i-2]) for i >= 2
    // And the answer is dp[n] where n is the length of cost, because step n is the top.

    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;

    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }

    return dp[n];
}

