public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }

    if (k > s.length()) {
        return false;
    }

    // Total number of binary strings of length k
    int required = 1 << k;

    // Early return if the string length is too short to contain all required substrings
    // The minimum length needed is required + k - 1
    if (s.length() < required + k - 1) {
        return false;
    }

    boolean[] seen = new boolean[required];
    int count = 0;
    int current = 0;

    // Rolling through the string to extract binary substrings of length k
    // We represent the substring as an integer for efficient hashing
    for (int i = 0; i < s.length(); i++) {
        // Add the new bit to the right side
        current = (current << 1) | (s.charAt(i) - '0');

        // If we have processed more than k characters, we need to mask out the bits
        // that are no longer in the window of length k
        if (i >= k) {
            current = current & (1 << k) - 1;
        }

        // Once we have exactly k characters in the window, we check if we've seen this substring
        if (i >= k - 1) {
            if (!seen[current]) {
                seen[current] = true;
                count++;
                // If we have found all possible binary strings, we can return early
                if (count == required) {
                    return true;
                }
            }
        }
    }

    return count == required;
}

