public int minInsertions(String s) {
    int minInsertions = 0;
    int openNeeded = 0;

    for (char c : s.toCharArray()) {
        if (c == ')') {
            if (openNeeded > 0) {
                openNeeded--;
            } else {
                minInsertions++;
            }
        } else {
            openNeeded++;
        }
    }

    minInsertions += openNeeded;
    return minInsertions;
}

