public int maxAbsoluteSum(int[] nums) {
    long maxSubSum = 0;
    long minSubSum = 0;
    int maxAbsolute = 0;

    for (long num : nums) {
        maxSubSum = Math.max(num, maxSubSum + num);
        minSubSum = Math.min(num, minSubSum + num);
        maxAbsolute = Math.max(maxAbsolute, (int) Math.max(Math.abs(maxSubSum), Math.abs(minSubSum)));
    }

    return maxAbsolute;
}

