public int findMinFibonacciNumbers(int k) {
    // Precompute Fibonacci numbers up to k
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int next = fibs.get(fibs.size() - 1) + fibs.get(fibs.size() - 2);
        if (next > k) break;
        fibs.add(next);
    }

    // Use greedy approach: pick the largest Fibonacci number <= remaining k
    int count = 0;
    for (int i = fibs.size() - 1; i >= 0 && k > 0; i--) {
        if (fibs.get(i) <= k) {
            k -= fibs.get(i);
            count++;
        }
    }
    return count;
}

