public String getSmallestString(int n, int k) {
    if (n <= 0) {
        return "";
    }

    char[] chars = new char[n];
    // Start with all 'a' characters, value = n
    for (int i = 0; i < n; i++) {
        chars[i] = 'a';
    }

    // Remaining value to distribute
    int remaining = k - n;

    // Check if remaining is valid: each position can add up to 25 (from 'a' to 'z')
    if (remaining < 0 || remaining > n * 25) {
        return "";
    }

    // Distribute the remaining value from right to left to keep leftmost characters as small as possible
    for (int i = n - 1; i >= 0; i--) {
        if (remaining <= 0) {
            break;
        }
        // How much can we add to this position? Up to 25
        int add = Math.min(remaining, 25);
        chars[i] = (char) ('a' + add);
        remaining -= add;
    }

    return new String(chars);
}

