public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }

    int count = 0;
    long factor = 1;
    while (factor <= n) {
        long high = n / (factor * 10);
        long current = (n / factor) % 10;
        long low = n % factor;

        if (current == 0) {
            count += (int)(high * factor);
        } else if (current == 1) {
            count += (int)(high * factor + low + 1);
        } else {
            count += (int)((high + 1) * factor);
        }

        factor *= 10;
    }

    return count;
}

