public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLen = 0;

    // dp[i][j][0] = longest horizontal line ending at (i, j)
    // dp[i][j][1] = longest vertical line ending at (i, j)
    // dp[i][j][2] = longest diagonal line ending at (i, j)
    // dp[i][j][3] = longest anti-diagonal line ending at (i, j)
    int[][][] dp = new int[m][n][4];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 0) {
                continue;
            }

            // Horizontal: check left neighbor
            if (j > 0) {
                dp[i][j][0] = dp[i][j - 1][0] + 1;
            } else {
                dp[i][j][0] = 1;
            }

            // Vertical: check top neighbor
            if (i > 0) {
                dp[i][j][1] = dp[i - 1][j][1] + 1;
            } else {
                dp[i][j][1] = 1;
            }

            // Diagonal: check top-left neighbor
            if (i > 0 && j > 0) {
                dp[i][j][2] = dp[i - 1][j - 1][2] + 1;
            } else {
                dp[i][j][2] = 1;
            }

            // Anti-diagonal: check top-right neighbor
            if (i > 0 && j < n - 1) {
                dp[i][j][3] = dp[i - 1][j + 1][3] + 1;
            } else {
                dp[i][j][3] = 1;
            }

            // Update max length
            maxLen = Math.max(maxLen, dp[i][j][0]);
            maxLen = Math.max(maxLen, dp[i][j][1]);
            maxLen = Math.max(maxLen, dp[i][j][2]);
            maxLen = Math.max(maxLen, dp[i][j][3]);
        }
    }

    return maxLen;
}

