        // If stack becomes empty, width of leftSmaller bars would be 'i - 0 - 1' or 'i-1'
        // else width of leftSmaller bars would be 'i - stack[top] - 1'
        leftSmaller[i] = (top == -1) ? (i - 1) : (i - stack[top] - 1);
        stack[++top] = i;
    }

    // reset top
    top = -1;

    // rightSmaller[i] will store the index of nearest bar to right of i 
    // which has smaller height than bars[i]'s height
    for (int i = n - 1; i >= 0; i--) {
        // Pop bars from stack as long as current bar's height is less than bar's height at stack top
        while (top != -1 && heights[i] <= heights[stack[top]]) {
            top--;
        }

        // If stack becomes empty, width of rightSmaller bars would be 'n - 1 - i' or 'n - i - 1'
        // else width of rightSmaller bars would be 'stack[top] - i - 1'
        rightSmaller[i] = (top == -1) ? (n - i - 1) : (stack[top] - i - 1);
        stack[++top] = i;
    }

    // Calculate area for each bar with width = (leftSmaller[i] + rightSmaller[i] + 1) and height = heights[i]
    for (int i = 0; i < n; i++) {
        int width = leftSmaller[i] + rightSmaller[i] + 1;
        int area = width * heights[i];
        maxArea = Math.max(maxArea, area);
    }

    return maxArea;
}

