public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }

    char[] digits = String.valueOf(n).toCharArray();
    int len = digits.length;

    // Find the rightmost digit that is smaller than the digit to its right
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit is found, the number is the largest possible permutation
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit on the right side of i that is greater than digits[i]
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the suffix starting at i+1 to get the smallest permutation of the suffix
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }

    String result = new String(digits);
    try {
        return Integer.parseInt(result);
    } catch (NumberFormatException e) {
        // Should not happen for valid inputs, but handled for safety
        return -1;
    }
}

