public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check if the three points form a valid triangle (non-degenerate)
    // Using the cross product method: area != 0
    // Area of triangle with vertices (x1,y1), (x2,y2), (x3,y3)
    // = 0.5 * |x1(y2 - y3) + x2(y3 - y1) + x3(y1 - y2)|
    // We can avoid division by 2 and absolute value by checking if the cross product is non-zero

    int cross = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1);

    return cross != 0;
}

