public static int calculateUniqueSum(int[] nums) {
        if (nums == null) {
            return 0;
        }

        java.util.Set<Integer> seen = new java.util.HashSet<>();
        java.util.Set<Integer> uniques = new java.util.HashSet<>();

        for (int num : nums) {
            if (!seen.add(num)) {
                uniques.remove(num);
            } else {
                uniques.add(num);
            }
        }

        int sum = 0;
        for (int num : uniques) {
            sum += num;
        }

        return sum;
    }

